#pragma once
#include <string_view>
namespace neurogenic { enum class CommandId { transport_start, transport_stop, pattern_generate, sample_load, sample_replace, sample_unload, sample_query }; constexpr std::string_view stable_id(CommandId id){switch(id){case CommandId::transport_start:return"transport.start";case CommandId::transport_stop:return"transport.stop";case CommandId::pattern_generate:return"pattern.generate";case CommandId::sample_load:return"sample.load.v1";case CommandId::sample_replace:return"sample.replace.v1";case CommandId::sample_unload:return"sample.unload.v1";case CommandId::sample_query:return"sample.query.v1";}return"unknown";} }
